class Solution {
public:
    vector<vector<int>> aggregateTwoTimeSeries(vector<vector<int>>& series1, vector<vector<int>>& series2) {
        set<int> ts;
        for (auto& e : series1) ts.insert(e[0]);
        for (auto& e : series2) ts.insert(e[0]);
        vector<vector<int>> res;
        for (int t : ts) {
            int v1 = 0, v2 = 0;
            auto i = lower_bound(series1.begin(), series1.end(), vector<int>{t, INT_MIN});
            if (i != series1.end()) v1 = (*i)[1];
            auto j = lower_bound(series2.begin(), series2.end(), vector<int>{t, INT_MIN});
            if (j != series2.end()) v2 = (*j)[1];
            res.push_back({t, v1 + v2});
        }
        return res;
    }
};

