class Solution {
    public int[][] aggregateTwoTimeSeries(int[][] series1, int[][] series2) {
        TreeSet<Integer> ts = new TreeSet<>();
        for (int[] e : series1) ts.add(e[0]);
        for (int[] e : series2) ts.add(e[0]);
        int[][] res = new int[ts.size()][];
        int k = 0;
        for (int t : ts) {
            int v1 = valAt(series1, t), v2 = valAt(series2, t);
            res[k++] = new int[]{t, v1 + v2};
        }
        return res;
    }
    private int valAt(int[][] s, int t) {
        int lo = 0, hi = s.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (s[mid][0] >= t) hi = mid; else lo = mid + 1;
        }
        return lo < s.length ? s[lo][1] : 0;
    }
}

