var aggregateTwoTimeSeries = function(series1, series2) {
    const ts = [...new Set([...series1.map(e => e[0]), ...series2.map(e => e[0])])].sort((a, b) => a - b);
    const valAt = (s, t) => {
        let lo = 0, hi = s.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (s[mid][0] >= t) hi = mid; else lo = mid + 1; }
        return lo < s.length ? s[lo][1] : 0;
    };
    return ts.map(t => [t, valAt(series1, t) + valAt(series2, t)]);
};

