class Solution {
public:
    vector<vector<int>> aggregateTwoTimeSeries(vector<vector<int>>& series1, vector<vector<int>>& series2) {
        int i = 0, j = 0, n = series1.size(), m = series2.size();
        long long cur1 = 0, cur2 = 0;
        vector<vector<int>> res;
        while (i < n || j < m) {
            long long t1 = i < n ? series1[i][0] : LLONG_MAX;
            long long t2 = j < m ? series2[j][0] : LLONG_MAX;
            long long t = min(t1, t2);
            if (t1 == t) { cur1 = series1[i++][1]; }
            if (t2 == t) { cur2 = series2[j++][1]; }
            res.push_back({(int)t, (int)(cur1 + cur2)});
        }
        return res;
    }
};

