class Solution {
    public int[][] aggregateTwoTimeSeries(int[][] series1, int[][] series2) {
        int i = 0, j = 0, n = series1.length, m = series2.length;
        long cur1 = 0, cur2 = 0;
        List<int[]> out = new ArrayList<>();
        while (i < n || j < m) {
            long t1 = i < n ? series1[i][0] : Long.MAX_VALUE;
            long t2 = j < m ? series2[j][0] : Long.MAX_VALUE;
            long t = Math.min(t1, t2);
            if (t1 == t) { cur1 = series1[i][1]; i++; }
            if (t2 == t) { cur2 = series2[j][1]; j++; }
            out.add(new int[]{(int) t, (int)(cur1 + cur2)});
        }
        return out.toArray(new int[0][]);
    }
}

