var aggregateTwoTimeSeries = function(series1, series2) {
    let i = 0, j = 0, cur1 = 0, cur2 = 0;
    const res = [];
    while (i < series1.length || j < series2.length) {
        const t1 = i < series1.length ? series1[i][0] : Infinity;
        const t2 = j < series2.length ? series2[j][0] : Infinity;
        const t = Math.min(t1, t2);
        if (t1 === t) { cur1 = series1[i][1]; i++; }
        if (t2 === t) { cur2 = series2[j][1]; j++; }
        res.push([t, cur1 + cur2]);
    }
    return res;
};
